insert into public.scripture_sources
  (id, reference, canonical, body, context, translation, attribution, provider, canonical_url, themes, approval_status, version)
values
  ('web:matthew-11-28', 'Matthew 11:28-30', '{"book":"Matthew","chapter":11,"verseStart":28,"verseEnd":30}'::jsonb, '“Come to me, all you who labor and are heavily burdened, and I will give you rest. Take my yoke upon you and learn from me, for I am gentle and lowly in heart; and you will find rest for your souls. For my yoke is easy, and my burden is light.”', 'Jesus has just contrasted the towns that would not receive him with the "little children" to whom the Father reveals himself. The invitation lands on people who are tired, not people who have succeeded.', '{"id":"web","name":"World English Bible","abbreviation":"WEB","rights":"Public domain. No permission required for reproduction."}'::jsonb, 'World English Bible (public domain)', 'local-web-corpus', 'https://ebible.org/web/MAT11.htm', array['weariness', 'burden', 'exhaustion', 'overwhelm', 'rest', 'anxiety']::text[], 'approved', 1),
  ('web:psalm-34-18', 'Psalm 34:18', '{"book":"Psalm","chapter":34,"verseStart":18,"verseEnd":null}'::jsonb, 'Yahweh is near to those who have a broken heart, and saves those who have a crushed spirit.', 'David writes this psalm after escaping danger by feigning madness. The nearness he describes is not a reward for composure — it is offered precisely to the crushed.', '{"id":"web","name":"World English Bible","abbreviation":"WEB","rights":"Public domain. No permission required for reproduction."}'::jsonb, 'World English Bible (public domain)', 'local-web-corpus', 'https://ebible.org/web/PSA34.htm', array['grief', 'heartbreak', 'loss', 'sorrow', 'despair', 'loneliness']::text[], 'approved', 1),
  ('web:philippians-4-6', 'Philippians 4:6-7', '{"book":"Philippians","chapter":4,"verseStart":6,"verseEnd":7}'::jsonb, 'In nothing be anxious, but in everything, by prayer and petition with thanksgiving, let your requests be made known to God. And the peace of God, which surpasses all understanding, will guard your hearts and your thoughts in Christ Jesus.', 'Paul writes from prison to a church he loves. The instruction is not to feel differently by force, but to move the worry somewhere — to name it in prayer rather than carry it silently.', '{"id":"web","name":"World English Bible","abbreviation":"WEB","rights":"Public domain. No permission required for reproduction."}'::jsonb, 'World English Bible (public domain)', 'local-web-corpus', 'https://ebible.org/web/PHP04.htm', array['anxiety', 'worry', 'fear', 'stress', 'panic', 'peace']::text[], 'approved', 1),
  ('web:matthew-6-33', 'Matthew 6:33-34', '{"book":"Matthew","chapter":6,"verseStart":33,"verseEnd":34}'::jsonb, 'But seek first God’s Kingdom and his righteousness; and all these things will be given to you as well. Therefore don’t be anxious for tomorrow, for tomorrow will be anxious for itself. Each day’s own evil is sufficient.', 'The close of a long passage about food, clothing, and the birds of the air. Jesus is speaking to ordinary material worry, not abstract priorities.', '{"id":"web","name":"World English Bible","abbreviation":"WEB","rights":"Public domain. No permission required for reproduction."}'::jsonb, 'World English Bible (public domain)', 'local-web-corpus', 'https://ebible.org/web/MAT06.htm', array['work', 'ambition', 'provision', 'priorities', 'money', 'striving', 'discernment']::text[], 'approved', 1),
  ('web:lamentations-3-22', 'Lamentations 3:22-23', '{"book":"Lamentations","chapter":3,"verseStart":22,"verseEnd":23}'::jsonb, 'It is because of Yahweh’s loving kindnesses that we are not consumed, because his compassion doesn’t fail. They are new every morning. Great is your faithfulness.', 'These lines sit in the middle of a book of grief over a ruined city. The hope is not a denial of the ruin; it is spoken from inside it.', '{"id":"web","name":"World English Bible","abbreviation":"WEB","rights":"Public domain. No permission required for reproduction."}'::jsonb, 'World English Bible (public domain)', 'local-web-corpus', 'https://ebible.org/web/LAM03.htm', array['hope', 'despair', 'endurance', 'morning', 'faithfulness', 'starting over']::text[], 'approved', 1),
  ('web:isaiah-41-10', 'Isaiah 41:10', '{"book":"Isaiah","chapter":41,"verseStart":10,"verseEnd":null}'::jsonb, 'Don’t you be afraid, for I am with you. Don’t be dismayed, for I am your God. I will strengthen you. Yes, I will help you. Yes, I will uphold you with the right hand of my righteousness.', 'Spoken to a people facing exile and a stronger enemy. The comfort offered is presence and help, not the removal of the threat.', '{"id":"web","name":"World English Bible","abbreviation":"WEB","rights":"Public domain. No permission required for reproduction."}'::jsonb, 'World English Bible (public domain)', 'local-web-corpus', 'https://ebible.org/web/ISA41.htm', array['fear', 'courage', 'uncertainty', 'change', 'strength']::text[], 'approved', 1),
  ('web:1-thessalonians-5-16', '1 Thessalonians 5:16-18', '{"book":"1 Thessalonians","chapter":5,"verseStart":16,"verseEnd":18}'::jsonb, 'Always rejoice. Pray without ceasing. In everything give thanks, for this is the will of God in Christ Jesus toward you.', 'The closing instructions of a letter to a young, pressured church. "In everything" is not "for everything" — gratitude here sits alongside hardship rather than replacing it.', '{"id":"web","name":"World English Bible","abbreviation":"WEB","rights":"Public domain. No permission required for reproduction."}'::jsonb, 'World English Bible (public domain)', 'local-web-corpus', 'https://ebible.org/web/1TH05.htm', array['gratitude', 'thanksgiving', 'joy', 'celebration', 'praise']::text[], 'approved', 1),
  ('web:matthew-18-21', 'Matthew 18:21-22', '{"book":"Matthew","chapter":18,"verseStart":21,"verseEnd":22}'::jsonb, 'Then Peter came and said to him, “Lord, how often shall my brother sin against me, and I forgive him? Until seven times?” Jesus said to him, “I don’t tell you until seven times, but, until seventy times seven.”', 'Peter thinks he is being generous. The answer reframes forgiveness from a quota to be met into a direction to keep walking.', '{"id":"web","name":"World English Bible","abbreviation":"WEB","rights":"Public domain. No permission required for reproduction."}'::jsonb, 'World English Bible (public domain)', 'local-web-corpus', 'https://ebible.org/web/MAT18.htm', array['forgiveness', 'resentment', 'conflict', 'relationships', 'bitterness']::text[], 'approved', 1),
  ('web:james-1-5', 'James 1:5-6', '{"book":"James","chapter":1,"verseStart":5,"verseEnd":6}'::jsonb, 'But if any of you lacks wisdom, let him ask of God, who gives to all liberally and without reproach, and it will be given to him. But let him ask in faith, without any doubting.', 'Written to scattered believers under pressure. The promise is not certainty about outcomes but wisdom for the next step, given "without reproach" — without being made to feel foolish for asking.', '{"id":"web","name":"World English Bible","abbreviation":"WEB","rights":"Public domain. No permission required for reproduction."}'::jsonb, 'World English Bible (public domain)', 'local-web-corpus', 'https://ebible.org/web/JAM01.htm', array['question', 'confusion', 'decision', 'discernment', 'wisdom', 'doubt']::text[], 'approved', 1),
  ('web:psalm-139-1', 'Psalm 139:1-3', '{"book":"Psalm","chapter":139,"verseStart":1,"verseEnd":3}'::jsonb, 'Yahweh, you have searched me, and you know me. You know my sitting down and my rising up. You perceive my thoughts from afar. You search out my path and my lying down, and are acquainted with all my ways.', 'A psalm about being fully known. It is often read as comfort and sometimes as exposure; the psalm itself holds both without resolving the tension.', '{"id":"web","name":"World English Bible","abbreviation":"WEB","rights":"Public domain. No permission required for reproduction."}'::jsonb, 'World English Bible (public domain)', 'local-web-corpus', 'https://ebible.org/web/PSA139.htm', array['loneliness', 'isolation', 'being known', 'identity', 'shame']::text[], 'approved', 1),
  ('web:1-corinthians-10-13', '1 Corinthians 10:13', '{"book":"1 Corinthians","chapter":10,"verseStart":13,"verseEnd":null}'::jsonb, 'No temptation has taken you except what is common to man. God is faithful, who will not allow you to be tempted above what you are able, but will with the temptation also make the way of escape, that you may be able to endure it.', 'Paul is writing to a divided church about pressure from the surrounding culture. The first move is de-isolating: this is "common to man," not evidence that you are uniquely broken.', '{"id":"web","name":"World English Bible","abbreviation":"WEB","rights":"Public domain. No permission required for reproduction."}'::jsonb, 'World English Bible (public domain)', 'local-web-corpus', 'https://ebible.org/web/1CO10.htm', array['temptation', 'struggle', 'habit', 'shame', 'endurance']::text[], 'approved', 1),
  ('web:proverbs-3-5', 'Proverbs 3:5-6', '{"book":"Proverbs","chapter":3,"verseStart":5,"verseEnd":6}'::jsonb, 'Trust in Yahweh with all your heart, and don’t lean on your own understanding. In all your ways acknowledge him, and he will make your paths straight.', 'Wisdom literature addressed to a young person making early decisions. "Don’t lean on your own understanding" is a caution against certainty, not against thinking.', '{"id":"web","name":"World English Bible","abbreviation":"WEB","rights":"Public domain. No permission required for reproduction."}'::jsonb, 'World English Bible (public domain)', 'local-web-corpus', 'https://ebible.org/web/PRO03.htm', array['decision', 'discernment', 'direction', 'calling', 'purpose', 'uncertainty']::text[], 'approved', 1),
  ('web:john-11-33', 'John 11:33-35', '{"book":"John","chapter":11,"verseStart":33,"verseEnd":35}'::jsonb, 'When Jesus therefore saw her weeping, and the Jews weeping who came with her, he groaned in the spirit, and was troubled, and said, “Where have you laid him?” They told him, “Lord, come and see.” Jesus wept.', 'Jesus is minutes away from raising Lazarus. He weeps anyway. The grief is not made unnecessary by knowing how it ends.', '{"id":"web","name":"World English Bible","abbreviation":"WEB","rights":"Public domain. No permission required for reproduction."}'::jsonb, 'World English Bible (public domain)', 'local-web-corpus', 'https://ebible.org/web/JHN11.htm', array['grief', 'death', 'mourning', 'loss', 'tears']::text[], 'approved', 1),
  ('web:ecclesiastes-4-9', 'Ecclesiastes 4:9-10', '{"book":"Ecclesiastes","chapter":4,"verseStart":9,"verseEnd":10}'::jsonb, 'Two are better than one, because they have a good reward for their labor. For if they fall, the one will lift up his fellow; but woe to him who is alone when he falls, and doesn’t have another to lift him up.', 'A book that stares hard at futility pauses here to make a plain, practical observation about company.', '{"id":"web","name":"World English Bible","abbreviation":"WEB","rights":"Public domain. No permission required for reproduction."}'::jsonb, 'World English Bible (public domain)', 'local-web-corpus', 'https://ebible.org/web/ECC04.htm', array['loneliness', 'community', 'friendship', 'isolation', 'help']::text[], 'approved', 1),
  ('web:john-14-27', 'John 14:27', '{"book":"John","chapter":14,"verseStart":27,"verseEnd":null}'::jsonb, 'Peace I leave with you. My peace I give to you; not as the world gives, I give to you. Don’t let your heart be troubled, neither let it be fearful.', 'Spoken on the last night before the crucifixion, to friends who are about to lose him. The peace offered is explicitly not the world’s kind — not the absence of trouble.', '{"id":"web","name":"World English Bible","abbreviation":"WEB","rights":"Public domain. No permission required for reproduction."}'::jsonb, 'World English Bible (public domain)', 'local-web-corpus', 'https://ebible.org/web/JHN14.htm', array['peace', 'fear', 'anxiety', 'comfort', 'hope']::text[], 'approved', 1)
insert into public.supporting_sources
  (id, kind, title, author, locator, edition, excerpt, tradition, canonical_url, rights, approval_status)
values
  ('ccel:augustine-confessions-1-1', 'historic_witness', 'Confessions', 'Augustine of Hippo', 'Book I, Chapter 1', 'Pusey translation, 1838', 'You have made us for yourself, and our heart is restless until it rests in you.', null, 'https://www.ccel.org/ccel/augustine/confessions.html', 'Public domain', 'approved'),
  ('ccel:kempis-imitation-1-1', 'historic_witness', 'The Imitation of Christ', 'Thomas à Kempis', 'Book I, Chapter 1', 'Benham translation, 1905', 'A humble countryman who serves God is better than a proud philosopher who watches the stars and neglects the knowledge of himself.', null, 'https://www.ccel.org/ccel/kempis/imitation.html', 'Public domain', 'approved'),
  ('ccel:julian-revelations-27', 'historic_witness', 'Revelations of Divine Love', 'Julian of Norwich', 'Chapter 27', 'Warrack edition, 1901', 'All shall be well, and all shall be well, and all manner of thing shall be well.', null, 'https://www.ccel.org/ccel/julian/revelations.html', 'Public domain', 'approved'),
  ('ccel:brother-lawrence-presence-4', 'historic_witness', 'The Practice of the Presence of God', 'Brother Lawrence of the Resurrection', 'Fourth Conversation', 'Fleming H. Revell edition, 1895', 'We ought not to be weary of doing little things for the love of God, who regards not the greatness of the work, but the love with which it is performed.', null, 'https://www.ccel.org/ccel/lawrence/practice.html', 'Public domain', 'approved'),
  ('ccel:chrysostom-homilies-matthew-38', 'historic_witness', 'Homilies on the Gospel of Matthew', 'John Chrysostom', 'Homily 38', 'Nicene and Post-Nicene Fathers, Series I, Vol. X', 'Prayer is the light of the spirit, true knowledge of God, mediating between God and man.', null, 'https://www.ccel.org/ccel/schaff/npnf110.html', 'Public domain', 'approved'),
  ('ccel:teresa-bookmark', 'historic_witness', 'The Bookmark of Saint Teresa', 'Teresa of Ávila', 'Complete text', 'Public-domain English rendering', 'Let nothing disturb you. Let nothing frighten you. All things are passing. God alone suffices.', 'Roman Catholic (Carmelite)', 'https://www.ccel.org/ccel/teresa/way.html', 'Public domain', 'approved')
